cd /workspace && python -c "
from pydicom import dcmread, Dataset
from pydicom.data import get_testdata_file
import json
ds = dcmread(get_testdata_file('waveform_ecg.dcm'))
js = ds.to_json(bulk_data_element_handler=lambda elem: 'http://example.com/bulk')
d = json.loads(js)
def walk(d):
    for k,v in d.items():
        if 'BulkDataURI' in v: print(k, v['vr'], v['BulkDataURI'])
        if v.get('vr')=='SQ' and 'Value' in v:
            for item in v['Value']: walk(item)
walk(d)
"
